<?php get_header(); $notice_id=absint($_GET['notice'] ?? 0); $notice_titles=[1=>ramser_energy_get('news_1'),2=>ramser_energy_get('news_2'),3=>ramser_energy_get('news_3')]; $news_page=get_page_by_path('news'); $news_url=$news_page ? get_permalink($news_page) : home_url('/news/'); ?>
<main class="inner-page"><section class="page-hero"><div class="container"><h1><?php echo esc_html($notice_id && isset($notice_titles[$notice_id]) ? $notice_titles[$notice_id] : ramser_energy_page_get('news_page_title')); ?></h1><p><?php echo esc_html(ramser_energy_page_get('news_page_intro')); ?></p></div></section><div class="container page-body"><?php if($notice_id && isset($notice_titles[$notice_id])): ?><article class="panel notice-detail"><div class="notice-detail-icon"><?php echo ramser_energy_ui_icon($notice_id===3?'service-schedule.svg':'service-outage.svg'); ?></div><span class="news-date">۱۴۰۴/۰۳/۲۵</span><h2><?php echo esc_html($notice_titles[$notice_id]); ?></h2><p><?php echo esc_html(ramser_energy_page_get('news_page_intro')); ?></p><p>این اطلاعیه از طریق مدیریت توزیع نیروی برق شهرستان رامسر منتشر شده است. برای دریافت آخرین اطلاعات و جزئیات مربوط به این موضوع، اطلاعیه‌های همین صفحه را دنبال کنید.</p><a class="section-link" href="<?php echo esc_url($news_url); ?>">← بازگشت به همه اطلاعیه‌ها</a></article><?php else: echo ramser_energy_img('news_page_image','page-cover'); ?><div class="news-page-grid"><?php for($i=1;$i<=3;$i++): $notice_url=add_query_arg('notice',$i,$news_url); ?><a class="panel news-card news-card-link" href="<?php echo esc_url($notice_url); ?>"><?php echo ramser_energy_img('news_'.$i.'_image','news-thumb'); ?><div><span class="news-date">۱۴۰۴/۰۳/۲۵</span><h2><?php echo esc_html(ramser_energy_get('news_'.$i)); ?></h2><p><?php echo esc_html(ramser_energy_page_get('news_page_intro')); ?></p><span class="section-link"><?php echo esc_html(ramser_energy_page_get('news_read')); ?> ←</span></div></a><?php endfor; ?></div><?php endif; ?></div></main><?php get_footer(); ?>